// Add a toggle action for planets display
StelActionMgr.addAction("actionShow_Planets", "Display Options", "Planets", SolarSystem, "setFlagPlanets(bool)", "P");

// Add an action without shortcut
StelActionMgr.addAction("actionReload_Data", "Tools", "Reload Solar System Data", SolarSystem, "reloadPlanets()");

// Add a global action (works even when Stellarium is not focused)
StelActionMgr.addAction("actionCapture_Screen", "Tools", "Take Screenshot", core, "screenshot()", "Ctrl+S", "", true);

// Add action with lambda
StelActionMgr.addAction("actionCustom_Message", "Tools", "Show Welcome Message", core, [=]() {
    core.debug("Welcome to Stellarium!");
}, "Ctrl+W");

// Add action to increase star magnitude
StelActionMgr.addAction("actionIncrease_Stars", "Display Options", "Increase Star Limit", core, [=]() {
    StarMgr.increaseStarsMagnitudeLimit();
}, "Ctrl+Up");

var action = StelActionMgr.findAction("actionShow_Planets");
if(action) {
    core.debug("Action found: " + action.getId());
    // Trigger the action
    action.trigger();
}

var action = StelActionMgr.findActionFromShortcut("P");
if(action) {
    core.debug("Action with shortcut P: " + action.getId());
}

var groups = StelActionMgr.getGroupList();
core.debug("Action groups: " + groups.length);
for(var i=0; i<groups.length; i++) {
    core.debug((i+1) + ". " + groups[i]);
}

var displayActions = StelActionMgr.getActionList("Display Options");
core.debug("Display Options actions: " + displayActions.length);
for(var i=0; i<displayActions.length; i++) {
    core.debug(displayActions[i].getId());
}

var shortcuts = StelActionMgr.getShortcutsList();
core.debug("Defined shortcuts: " + shortcuts.length);
for(var i=0; i<Math.min(10, shortcuts.length); i++) {
    core.debug(shortcuts[i]);
}

// Change a shortcut and save
var action = StelActionMgr.findAction("actionShow_Planets");
action.setShortcut("Ctrl+Shift+P");
StelActionMgr.saveShortcuts();
core.debug("Shortcuts saved");

// Reset all keyboard shortcuts to defaults
StelActionMgr.restoreDefaultShortcuts();
core.debug("All shortcuts restored to defaults");

var action = StelActionMgr.findAction("actionShow_Planets");
StelActionMgr.restoreDefaultShortcut(action);
core.debug("Shortcut restored for action");

// Temporarily disable all actions
StelActionMgr.setAllActionsEnabled(false);
// ... do something (e.g., edit shortcuts) ...
StelActionMgr.setAllActionsEnabled(true);

var action = StelActionMgr.findAction("actionShow_Planets");
if(action.isCheckable()) {
    core.debug("Action is toggleable");
    core.debug("Current state: " + action.isChecked());
}

var action = StelActionMgr.findAction("actionShow_Planets");
if(action.isChecked()) {
    core.debug("Planets are currently visible");
} else {
    core.debug("Planets are hidden");
}

var action = StelActionMgr.findAction("actionCapture_Screen");
if(action.isGlobal()) {
    core.debug("This action works even when Stellarium is not focused");
}

var action = StelActionMgr.findAction("actionShow_Planets");
action.setShortcut("Ctrl+Shift+P");
StelActionMgr.saveShortcuts();
core.debug("Shortcut changed to Ctrl+Shift+P");

var action = StelActionMgr.findAction("actionShow_Planets");
action.setAltShortcut("P");
StelActionMgr.saveShortcuts();

var action = StelActionMgr.findAction("actionShow_Planets");
// Check if 'P' matches
var seq = new QKeySequence("P");
var match = action.matches(seq);
if(match == 1) { // ExactMatch
    core.debug("'P' exactly matches this action");
}

var action = StelActionMgr.findAction("actionShow_Planets");
var shortcut = action.getShortcut();
core.debug("Primary shortcut: " + shortcut.toString());

var action = StelActionMgr.findAction("actionShow_Planets");
var altShortcut = action.getAltShortcut();
if(!altShortcut.isEmpty()) {
    core.debug("Alternative shortcut: " + altShortcut.toString());
}

var action = StelActionMgr.findAction("actionShow_Planets");
if(action.isCheckable()) {
    // Turn on planets
    action.setChecked(true);
    core.debug("Planets enabled");
}

var action = StelActionMgr.findAction("actionShow_Planets");
// Trigger the action programmatically
action.trigger();

var action = StelActionMgr.findAction("actionShow_Planets");
if(action.isCheckable()) {
    // Toggle planets on/off
    action.toggle();
    core.debug("Planets toggled, new state: " + action.isChecked());
}
